    this.props.onChangeRaw(event, { date, formattedDate });
  }
  this.setSelected(date, event, false, monthSelectedIn);
  if (this.props.showDateSelect) {
    this.setState({ isRenderAriaLiveMessage: true });
  }
  if (!this.props.shouldCloseOnSelect || this.props.showTimeSelect) {
    this.setPreSelection(date);
  } else if (isDateSelectionComplete) {
    this.setOpen(false);
  }
};

// setSelected is called either from handleChange (user typed date into textbox and it was parsed) or handleSelect (user selected date from calendar using mouse or keyboard)
setSelected = (
  date: Date | null,
  event?: React.MouseEvent<HTMLElement> | React.KeyboardEvent<HTMLElement>,
  keepInput?: boolean,
  monthSelectedIn?: number,
) => {
  const { timeZone } = this.props;

  // If timezone is specified, convert the selected date from zoned time to UTC
  // This ensures the onChange callback receives a proper UTC Date object
  let changedDate = date;
  if (changedDate && timeZone) {
    changedDate = fromZonedTime(changedDate, timeZone);
  }

  // Early return if selected year/month/day is disabled
  if (this.props.showYearPicker) {
    if (
      changedDate !== null &&
      isYearDisabled(getYear(changedDate), this.props)
    ) {
      return;
    }
  } else if (this.props.showMonthYearPicker) {
    if (changedDate !== null && isMonthDisabled(changedDate, this.props)) {
      return;
    }
  } else {
    if (changedDate !== null && isDayDisabled(changedDate, this.props)) {
      return;
    }
  }

  const {
    onChange,
    selectsRange,
    startDate,
    endDate,
    selectsMultiple,
    selectedDates,
    minTime,
    swapRange,
  } = this.props;

  if (
    !isEqual(this.props.selected, changedDate) ||
    this.props.allowSameDay ||
    selectsRange ||
    selectsMultiple
  ) {
    if (changedDate !== null) {
      // Preserve previously selected time if only date is currently being changed
      if (
        this.props.selected &&
        (!keepInput ||
          (!this.props.showTimeSelect &&
            !this.props.showTimeSelectOnly &&
            !this.props.showTimeInput))
      ) {
        changedDate = setTime(changedDate, {
          hour: getHours(this.props.selected),
          minute: getMinutes(this.props.selected),
          second: getSeconds(this.props.selected),
        });
      }

      // If minTime is present then set the time to minTime
      if (
        !keepInput &&
        (this.props.showTimeSelect || this.props.showTimeSelectOnly)
      ) {
        if (minTime) {
          changedDate = setTime(changedDate, {
            hour: minTime.getHours(),
            minute: minTime.getMinutes(),
            second: minTime.getSeconds(),
          });
        }
      }

      if (!this.props.inline) {
        this.setState({
          preSelection: changedDate,
        });
      }
      if (!this.props.focusSelectedMonth) {
        this.setState({ monthSelectedIn: monthSelectedIn });
      }
    }

    if (selectsRange) {
      const onChangeRange = onChange as OnChangeRange | undefined;
      const noRanges = !startDate && !endDate;
      const hasStartRange = startDate && !endDate;
      const hasOnlyEndRange = !startDate && !!endDate;
      const isRangeFilled = startDate && endDate;
      if (noRanges) {
        onChangeRange?.([changedDate, null], event);
      } else if (hasStartRange) {
        if (changedDate === null) {
          onChangeRange?.([null, null], event);
        } else if (isDateBefore(changedDate, startDate)) {
          if (swapRange) {
            onChangeRange?.([changedDate, startDate], event);
          } else {
            onChangeRange?.([changedDate, null], event);
          }
        } else {
          onChangeRange?.([startDate, changedDate], event);
        }
      } else if (hasOnlyEndRange) {
        if (changedDate && isDateBefore(changedDate, endDate)) {
          onChangeRange?.([changedDate, endDate], event);
        } else {
          onChangeRange?.([changedDate, null], event);
        }
      }
      if (isRangeFilled) {
        onChangeRange?.([changedDate, null], event);
      }
    } else if (selectsMultiple) {
      const onChangeMultiple = onChange as OnChangeMultiple | undefined;
      if (changedDate !== null) {
        if (!selectedDates?.length) {
          onChangeMultiple?.([changedDate], event);
        } else {
          const isChangedDateAlreadySelected = selectedDates.some(
            (selectedDate) => isSameDay(selectedDate, changedDate),
          );

          if (isChangedDateAlreadySelected) {
            const nextDates = selectedDates.filter(
              (selectedDate) => !isSameDay(selectedDate, changedDate),
            );

            onChangeMultiple?.(nextDates, event);
          } else {
            onChangeMultiple?.([...selectedDates, changedDate], event);
          }
        }
      }
    } else {
      (onChange as OnChangeSingle | undefined)?.(changedDate, event);
    }
  }

  if (!keepInput) {
    this.props.onSelect?.(changedDate, event);
    this.setState({ inputValue: null });
  }
};

// When checking preSelection via min/maxDate, times need to be manipulated via getStartOfDay/getEndOfDay
setPreSelection = (date?: Date | null): void => {
  if (this.props.readOnly) return;
  const hasMinDate = isDate(this.props.minDate);
  const hasMaxDate = isDate(this.props.maxDate);
  let isValidDateSelection = true;
  if (date) {
    const dateStartOfDay = getStartOfDay(date);
  }
  this.setState({ inputValue: null });
};

onInputClick = (): void => {
  if (!this.props.disabled && !this.props.readOnly) {
    this.setOpen(true);
  }

  this.props.onInputClick?.();
};

handleTimeOnlyArrowKey = (eventKey: string): void => {
  const currentTime =
    safeToDate(this.props.selected) || this.state.preSelection || newDate();
  const timeIntervals = this.props.timeIntervals ?? 30;
  const dateFormat =
    this.props.dateFormat ?? DatePicker.defaultProps.dateFormat;
  const formatStr = Array.isArray(dateFormat) ? dateFormat[0] : dateFormat;

  const baseDate = getStartOfDay(currentTime);
  const currentMinutes = getHours(currentTime) * 60 + getMinutes(currentTime);

  const maxMinutes = 23 * 60 + 60 - timeIntervals; // Cap at last valid interval of the day
  let newTime: Date;
  if (eventKey === KeyType.ArrowUp) {
    const newMinutes = Math.max(0, currentMinutes - timeIntervals);
    newTime = addMinutes(baseDate, newMinutes);
  } else {
    const newMinutes = Math.min(maxMinutes, currentMinutes + timeIntervals);
    newTime = addMinutes(baseDate, newMinutes);
  }

  const formattedTime = formatDate(
    newTime,
    formatStr || DatePicker.defaultProps.dateFormat,
    this.props.locale,
  );
  this.setState({
    preSelection: newTime,
    inputValue: formattedTime,
  });

  if (this.props.selectsRange || this.props.selectsMultiple) {
    return;
  }

  const selected = this.props.selected
    ? this.props.selected
    : this.getPreSelection();
  const changedDate = this.props.selected
    ? newTime
    : setTime(selected, {
        hour: getHours(newTime),
        minute: getMinutes(newTime),
      });

  (this.props.onChange as OnChangeSingle | undefined)?.(changedDate);

  if (this.props.showTimeSelectOnly || this.props.showTimeSelect) {
    this.setState({ isRenderAriaLiveMessage: true });
  }

  requestAnimationFrame(() => {
    this.scrollToTimeOption(newTime);
  });

import React from "react";
import { render, fireEvent } from "@testing-library/react";
import DatePicker from "../index";
import * as dateUtils from "../date_utils";

const {
  toZonedTime,
  fromZonedTime,
  formatInTimeZone,
  nowInTimeZone,
  __resetDateFnsTzCache,
  __setDateFnsTzNull,
} = dateUtils;

describe("Timezone utility functions", () => {
  // Use a fixed UTC date for consistent testing
  const testDate = new Date("2024-06-15T12:00:00Z");

  describe("toZonedTime", () => {
    it("should return the original date when no timezone is provided", () => {
      const result = toZonedTime(testDate);
      expect(result).toBe(testDate);
    });

    it("should return the original date when timezone is undefined", () => {
      const result = toZonedTime(testDate, undefined);
      expect(result).toBe(testDate);
    });

    it("should convert UTC date to specified timezone", () => {
      // 2024-06-15T12:00:00Z in America/New_York (EDT, UTC-4) should be 08:00
      const result = toZonedTime(testDate, "America/New_York");
      expect(result).toBeInstanceOf(Date);
      // The result should represent 08:00 in New York time
      expect(result.getHours()).toBe(8);
      expect(result.getMinutes()).toBe(0);
    });

    it("should handle UTC timezone", () => {
      const result = toZonedTime(testDate, "UTC");
      expect(result).toBeInstanceOf(Date);
      // toZonedTime returns a date that represents the time in the target timezone
      // When displayed locally, it should show 12:00 (the UTC time)
      expect(result.getHours()).toBe(12);
      expect(result.getMinutes()).toBe(0);
    });

    it("should handle different timezones", () => {
      // Test with Europe/London (BST in June, UTC+1)
      const londonResult = toZonedTime(testDate, "Europe/London");
      expect(londonResult).toBeInstanceOf(Date);
      // 12:00 UTC should be 13:00 in London during BST
      expect(londonResult.getHours()).toBe(13);

      // Test with Asia/Tokyo (JST, UTC+9)
      const tokyoResult = toZonedTime(testDate, "Asia/Tokyo");
      expect(tokyoResult).toBeInstanceOf(Date);
      // 12:00 UTC should be 21:00 in Tokyo
      expect(tokyoResult.getHours()).toBe(21);
    });
  });

  describe("fromZonedTime", () => {
    it("should return the original date when no timezone is provided", () => {
      const result = fromZonedTime(testDate);
      expect(result).toBe(testDate);
    });

    it("should return the original date when timezone is undefined", () => {
      const result = fromZonedTime(testDate, undefined);
      expect(result).toBe(testDate);
    });

    it("should convert zoned time to UTC", () => {
      // Create a date representing 08:00 in New York (which is 12:00 UTC in June)
      const nyDate = new Date("2024-06-15T08:00:00");
      const result = fromZonedTime(nyDate, "America/New_York");
      expect(result).toBeInstanceOf(Date);
      // The result should be 12:00 UTC
      expect(result.getUTCHours()).toBe(12);
    });

    it("should handle UTC timezone", () => {
      const utcDate = new Date("2024-06-15T12:00:00");
      const result = fromZonedTime(utcDate, "UTC");
      expect(result).toBeInstanceOf(Date);
      expect(result.getUTCHours()).toBe(12);
    });

    it("should be inverse of toZonedTime", () => {
      const timezone = "America/Los_Angeles";
      const zonedTime = toZonedTime(testDate, timezone);
      const backToUtc = fromZonedTime(zonedTime, timezone);
      // The round-trip should give us back the original UTC time
      expect(backToUtc.getTime()).toBe(testDate.getTime());
    });
  });

  describe("formatInTimeZone", () => {
    it("should use standard format when no timezone is provided", () => {
      const result = formatInTimeZone(testDate, "yyyy-MM-dd");
      // Without timezone, it should use the standard format function
      expect(result).toBe("2024-06-15");
    });

    it("should format date in specified timezone", () => {
      // 2024-06-15T12:00:00Z formatted in America/New_York should show 08:00
      const result = formatInTimeZone(
        testDate,
        "yyyy-MM-dd HH:mm",
        "America/New_York",
      );
      expect(result).toBe("2024-06-15 08:00");
    });

    it("should format date in UTC timezone", () => {
      const result = formatInTimeZone(testDate, "yyyy-MM-dd HH:mm", "UTC");
      expect(result).toBe("2024-06-15 12:00");
    });

    it("should format date in different timezones", () => {
      // Europe/London (BST in June, UTC+1)
      const londonResult = formatInTimeZone(testDate, "HH:mm", "Europe/London");
      expect(londonResult).toBe("13:00");

      // Asia/Tokyo (JST, UTC+9)
      const tokyoResult = formatInTimeZone(testDate, "HH:mm", "Asia/Tokyo");
      expect(tokyoResult).toBe("21:00");
    });

    it("should handle complex format strings", () => {
      const result = formatInTimeZone(
        testDate,
        "EEEE, MMMM d, yyyy 'at' h:mm a",
        "America/New_York",
      );
      expect(result).toBe("Saturday, June 15, 2024 at 8:00 AM");
    });
  });

  describe("nowInTimeZone", () => {
    it("should return current date when no timezone is provided", () => {
      const before = new Date();
      const result = nowInTimeZone();
      const after = new Date();

      expect(result.getTime()).toBeGreaterThanOrEqual(before.getTime());
      expect(result.getTime()).toBeLessThanOrEqual(after.getTime());
    });

    it("should return current date in specified timezone", () => {
      const result = nowInTimeZone("America/New_York");
      expect(result).toBeInstanceOf(Date);
      // We can't test exact time, but we can verify it's a valid date
      expect(result.getTime()).not.toBeNaN();
    });

    it("should return current date in UTC", () => {
      const result = nowInTimeZone("UTC");
      expect(result).toBeInstanceOf(Date);
      expect(result.getTime()).not.toBeNaN();
    });
  });
});

describe("Timezone utility functions - edge cases", () => {
  it("should handle empty string timezone", () => {
    const testDate = new Date("2024-06-15T12:00:00Z");
    const result = toZonedTime(testDate, "");
    // Empty string is falsy, so should return original date
    expect(result).toBe(testDate);
  });

  it("should handle various date inputs", () => {
    const dates = [
      new Date("2024-01-01T00:00:00Z"),
      new Date("2024-06-15T12:30:45Z"),
      new Date("2024-12-31T23:59:59Z"),
    ];

    dates.forEach((date) => {
      const result = toZonedTime(date);
      expect(result).toBe(date);
    });
  });

  it("should handle DST transitions", () => {
    // Test a date during DST (summer)
    const summerDate = new Date("2024-07-15T12:00:00Z");
    const summerResult = formatInTimeZone(
      summerDate,
      "HH:mm",
      "America/New_York",
    );
    expect(summerResult).toBe("08:00"); // EDT (UTC-4)

    // Test a date outside DST (winter)
    const winterDate = new Date("2024-01-15T12:00:00Z");
    const winterResult = formatInTimeZone(
      winterDate,
      "HH:mm",
      "America/New_York",
    );
    expect(winterResult).toBe("07:00"); // EST (UTC-5)
  });

  it("should handle dates at midnight", () => {
    const midnightUtc = new Date("2024-06-15T00:00:00Z");
    const result = formatInTimeZone(
      midnightUtc,
      "yyyy-MM-dd HH:mm",
      "America/New_York",
    );
    // Midnight UTC is 8 PM previous day in New York (EDT)
    expect(result).toBe("2024-06-14 20:00");
  });

  it("should handle dates at end of day", () => {
    const endOfDayUtc = new Date("2024-06-15T23:59:59Z");
    const result = formatInTimeZone(
      endOfDayUtc,
      "yyyy-MM-dd HH:mm",
      "Asia/Tokyo",
    );
    // 23:59 UTC is 08:59 next day in Tokyo (JST, UTC+9)
    expect(result).toBe("2024-06-16 08:59");
  });
});

describe("Timezone utility functions - integration", () => {
  it("should correctly round-trip dates through timezone conversions", () => {
    const originalDate = new Date("2024-06-15T15:30:00Z");
    const timezones = [
      "America/New_York",
      "America/Los_Angeles",
