describe("Multiple Dates Selected", function () {
  function getDatePicker(
    extraProps: Partial<
      Pick<
        DatePickerProps,
        "shouldCloseOnSelect" | "disabledKeyboardNavigation" | "onSelect"
      >
    > &
      OmitUnion<
        DatePickerProps,
